1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	  isComponent: boolean;
66	}
67	
68	const ITEM_SPECS = {
69	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
70	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
71	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
72	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
73	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
75	} as const satisfies Record<string, ItemSpec>;
76	
77	type KnownItemType = keyof typeof ITEM_SPECS;
78	
79	const isKnownItemType = (type: string): type is KnownItemType =>
80	  type in ITEM_SPECS;
81	
82	// The office insures only what its price list names. An unknown type has no
83	// premium and no insurance value, so there is nothing to quote — the whole
84	// scenario is rejected rather than priced at zero.
85	const specForItem = (item: Item): ItemSpec => {
86	  if (!isKnownItemType(item.type)) {
87	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
88	  }
89	  return ITEM_SPECS[item.type];
90	};
91	
92	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
93	
94	const BLOCK_SIZE = 3;
95	
96	const BLOCK_BASE_PREMIUM = 60;
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// "Alike" means the same exact type, not merely the same family: two runes and
102	// a moonstone are three components but not three alike ones, so grouping them
103	// by type keeps them apart and denies them the block price.
104	const groupByType = (items: Item[]): Item[][] => {
105	  const groups = new Map<string, Item[]>();
106	  for (const item of items) {
107	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
108	  }
109	  return [...groups.values()];
110	};
111	
112	// A block is three alike COMPONENTS — the discount is offered on runes and
113	// moonstones, not on swords. It is also not carved out of a larger group: the
114	// price applies only when the group holds exactly three (7 runes cost 7 × 25,
115	// not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only ever
116	// passes a single group from groupByType.
117	const isBlock = (group: Item[]): boolean =>
118	  group.length === BLOCK_SIZE && group.every((item) => specForItem(item).isComponent);
119	
120	const basePremiumForGroup = (group: Item[]): number =>
121	  isBlock(group) ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumForItem));
122	
123	const basePremiumForItems = (items: Item[]): number =>
124	  sum(groupByType(items).map(basePremiumForGroup));
125	
126	const CURSE_SURCHARGE = 0.5;
127	
128	// Every modifier is an additive percentage of its OWN base — modifiers never
129	// compound with each other. Item-scoped modifiers take the affected item's base
130	// premium as their base; policy-scoped modifiers take the policy base premium
131	// (the sum of all item base premiums). So the total is always
132	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
133	const modifierAmount = (rate: number, base: number): number => rate * base;
134	
135	const ENCHANTMENT_SURCHARGE = 0.3;
136	
137	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
138	
139	const isCursed = (item: Item): boolean => item.cursed === true;
140	
141	const attractsEnchantmentSurcharge = (item: Item): boolean =>
142	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
143	
144	interface ItemModifier {
145	  rate: number;
146	  appliesTo: (item: Item) => boolean;
147	}
148	
149	// Each item-scoped modifier is a row: a rate and the condition under which it
150	// applies. The predicate names the modifier, so a row needs no separate label.
151	// Adding a modifier means adding a row, not a new branch.
152	const ITEM_MODIFIERS: ItemModifier[] = [
153	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
154	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
155	];
156	
157	const itemModifierRates = (item: Item): number[] =>
158	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
159	    (modifier) => modifier.rate,
160	  );
161	
162	const LOYALTY_DISCOUNT = 0.2;
163	
164	const LOYALTY_THRESHOLD_YEARS = 2;
165	
166	const isLongStanding = (customer: Customer): boolean =>
167	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
168	
169	// Discounts are surcharges with the sign flipped: expressing one as a negative
170	// rate lets it flow through the same additive sum as every surcharge, with no
171	// separate subtraction step. Discount constants stay positive magnitudes and
172	// are negated here, at the point of use, so the direction is visible in the
173	// rate list rather than buried in a constant's sign.
174	const asDiscount = (rate: number): number => -rate;
175	
176	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
177	
178	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
179	
180	// Policy-scoped modifiers apply to the policy base premium. Unlike item
181	// modifiers they select on the customer and on the quote's position in the
182	// scenario rather than on an item.
183	//
184	// The initial-assessment surcharge applies to every quote: each item is treated
185	// as a first insurance regardless of customer history. The follow-up discount
186	// is what distinguishes a customer's later contracts.
187	const policyModifierRates = (
188	  customer: Customer,
189	  isFollowUpContract: boolean,
190	): number[] => [
191	  INITIAL_ASSESSMENT_SURCHARGE,
192	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
193	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
194	];
195	
196	const itemModifiersTotal = (items: Item[]): number =>
197	  sum(
198	    items.flatMap((item) =>
199	      itemModifierRates(item).map((rate) =>
200	        modifierAmount(rate, basePremiumForItem(item)),
201	      ),
202	    ),
203	  );
204	
205	const policyModifiersTotal = (
206	  policyBasePremium: number,
207	  customer: Customer,
208	  isFollowUpContract: boolean,
209	): number =>
210	  sum(
211	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
212	      modifierAmount(rate, policyBasePremium),
213	    ),
214	  );
215	
216	// All amounts are rounded to whole G in the MHPCO's favour. Which way that
217	// points depends on which way the money flows: a premium comes in, so it rounds
218	// up; a payout goes out, so it rounds down.
219	//
220	// Two functions rather than one taking a direction, so that knowing which way
221	// favour points for a given kind of money stays here. A direction parameter
222	// would push that back onto every caller — the one thing these exist to answer.
223	const roundPremiumInMHPCOsFavour = (amount: number): number =>
224	  Math.ceil(amount);
225	
226	const roundPayoutInMHPCOsFavour = (amount: number): number =>
227	  Math.floor(amount);
228	
229	const quotePremium = (
230	  items: Item[],
231	  customer: Customer,
232	  isFollowUpContract: boolean,
233	): number => {
234	  const policyBasePremium = basePremiumForItems(items);
235	  return roundPremiumInMHPCOsFavour(
236	    policyBasePremium +
237	      itemModifiersTotal(items) +
238	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
239	      PROCESSING_FEE,
240	  );
241	};
242	
243	const insuranceValueForItem = (item: Item): number =>
244	  specForItem(item).insuranceValue;
245	
246	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
247	// figure from ITEM_SPECS, but the premium side groups by type first so a block
248	// of three alike components can be priced as one; this side never groups. Three
249	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
250	// discount on the price of cover, not a reduction of the cover bought.
251	//
252	// So the near-symmetry is a false friend: factoring the two into one traversal
253	// would read as tidier and would silently make blocks shrink the insurance sum.
254	// The repetition of `sum(items.map(...))` is the price of keeping them free to
255	// diverge, and is paid on purpose.
256	const insuranceSum = (items: Item[]): number =>
257	  sum(items.map(insuranceValueForItem));
258	
259	const CAP_MULTIPLE = 2;
260	
261	// The cap is twice the insurance sum — the value the items are insured FOR, so
262	// it is computed from the items alone and never from the premium. Curses,
263	// enchantments and loyalty change what a policy costs without changing what it
264	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
265	// separation visible at the one place a policy is created.
266	const capForItems = (items: Item[]): number =>
267	  CAP_MULTIPLE * insuranceSum(items);
268	
269	const DEDUCTIBLE = 100;
270	
271	interface Policy {
272	  items: Item[];
273	  remainingCap: number;
274	}
275	
276	// Steps are not independent: a quote's premium depends on how many quotes came
277	// before it, and a claim draws down the cap of a policy an earlier quote
278	// created. So a step is a function from state to (result, next state), and the
279	// scenario is a fold over that — not a map, which would promise an independence
280	// the steps do not have.
281	//
282	// Policies are keyed by the index of the quote step that created them: a claim
283	// step names its policy by that zero-based index.
284	interface ScenarioState {
285	  quotesSoFar: number;
286	  policies: Map<number, Policy>;
287	}
288	
289	// A fresh state per run, not a shared constant. The Map makes the difference:
290	// a module-level seed would hand every scenario the same one. Nothing mutates
291	// it today — withPolicy copies before it writes — so a shared seed would work,
292	// but only by an invariant that lives in another function and would have to be
293	// rediscovered by the next writer. Building the seed per run makes each
294	// scenario's independence a property of the code rather than a promise about it.
295	const initialState = (): ScenarioState => ({
296	  quotesSoFar: 0,
297	  policies: new Map(),
298	});
299	
300	interface StepOutcome {
301	  result: StepResult;
302	  state: ScenarioState;
303	}
304	
305	// Both operations end by filing a policy under its quote's index — a claim
306	// re-files the same policy with a drawn-down cap. Naming that once keeps the
307	// Map out of the operations, so neither has to know how policies are stored.
308	const withPolicy = (
309	  state: ScenarioState,
310	  policyIndex: number,
311	  policy: Policy,
312	): ScenarioState => ({
313	  ...state,
314	  policies: new Map(state.policies).set(policyIndex, policy),
315	});
316	
317	// What makes a contract a follow-up is that the customer has already been
318	// quoted in this scenario — the first quote is the initial contract, every
319	// later one follows it. Named because the bare comparison is the
320	// follow-up-contract rule itself, not an index check: it is what decides
321	// whether the 15 % discount applies.
322	const isFollowUpContract = (state: ScenarioState): boolean =>
323	  state.quotesSoFar > 0;
324	
325	const runQuote = (
326	  step: QuoteStep,
327	  customer: Customer,
328	  state: ScenarioState,
329	  stepIndex: number,
330	): StepOutcome => ({
331	  result: {
332	    premium: quotePremium(step.items, customer, isFollowUpContract(state)),
333	  },
334	  state: withPolicy(
335	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
336	    stepIndex,
337	    {
338	      items: step.items,
339	      remainingCap: capForItems(step.items),
340	    },
341	  ),
342	});
343	
344	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
345	
346	const REDUCED_REIMBURSEMENT_RATE = 0.5;
347	
348	const FULL_REIMBURSEMENT_RATE = 1;
349	
350	// Reads enchantment like the premium-side surcharge rule, but is a different
351	// rule with its own level: this one halves what a claim pays out, that one
352	// raises what a policy costs. Sharing a predicate would tie two levels that the
353	// spec lets move independently, so the shape is repeated deliberately.
354	const qualifiesForReducedReimbursement = (item: Item): boolean =>
355	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
356	
357	// The reimbursement rate is decided first, then one deductible comes off.
358	//
359	// The dragon-material clause is absent on purpose, not by oversight. It promises
360	// full reimbursement of the damage before the deductible — which is exactly what
361	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
362	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
363	// them the two facts leave the clause with no input it can move: dragon material
364	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
365	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
366	// would add a branch no test could ever tell from the default — a distinction
367	// the domain does not make.
368	const reimbursementRate = (item: Item): number =>
369	  qualifiesForReducedReimbursement(item)
370	    ? REDUCED_REIMBURSEMENT_RATE
371	    : FULL_REIMBURSEMENT_RATE;
372	
373	const payoutForDamage = (damage: Damage, item: Item): number =>
374	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
375	
376	// Returns AN insured item of the damaged type, not THE damaged one — a policy
377	// can cover two swords, so the type does not name a unique item. Two damage
378	// entries of the same type are both answered with the same first match.
379	//
380	// That is sound today because the answer is used solely to read payout
381	// attributes (the reimbursement rate), and the covered case — two damages
382	// against two swords — insures identical swords, which read the same either
383	// way. The deductible is charged per damage entry, not per matched item, so
384	// counting is unaffected too.
385	//
386	// One thing would break it, not yet under test: two swords with DIFFERENT
387	// attributes (say enchantment 3 and 9). Both damages would take the first
388	// sword's rate; the second should take its own. This lookup must then become a
389	// pairing that consumes what it matches. The honest name marks that spot.
390	//
391	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
392	// throws unless every claimed type is covered at least as many times as it is
393	// named — so by the time this runs, a match exists for every damage entry. Both
394	// ways it could fail are covered by tests: claiming a type more often than it is
395	// insured, and claiming a type the policy does not cover at all.
396	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
397	  policy.items.find((item) => item.type === damage.itemType)!;
398	
399	// Counts how many times each value occurs. Deliberately typed on strings rather
400	// than on Item: the guard below tallies two different things (item types held
401	// and item types named by damages) and only their counts are ever compared, so
402	// the tally has no business knowing what the strings mean.
403	const tally = (values: string[]): Map<string, number> => {
404	  const counts = new Map<string, number>();
405	  for (const value of values) {
406	    counts.set(value, (counts.get(value) ?? 0) + 1);
407	  }
408	  return counts;
409	};
410	
411	// Every damage entry must claim an insured item of its own, so a type cannot be
412	// damaged more times than the policy covers it. One rule, three error cases the
413	// spec states separately — all of them the same comparison at different counts:
414	//
415	//   claimed > insured, insured ≥ 1  a type damaged more often than it is insured
416	//   claimed > insured, insured = 0  a type the policy does not cover at all
417	//   claimed > insured, insured = 0  a type the office does not insure at all
418	//
419	// The last two differ only in why the count is zero, which is why neither needs
420	// its own test. An uninsured type and an unknown type are both covered 0 times
421	// against a claimed 1. In particular the unknown type never reaches a lookup in
422	// ITEM_SPECS: a broomstick is not in THIS policy, which is the more precise
423	// complaint than whether the office insures broomsticks in general. The quote
424	// path is where the price list is consulted and where an unknown type is
425	// rejected as uninsurable.
426	//
427	// Checked before any payout is computed: the spec rejects the whole claim, not
428	// just the surplus entries.
429	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
430	  const insured = tally(policy.items.map((item) => item.type));
431	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
432	  for (const [type, claimedCount] of claimed) {
433	    const insuredCount = insured.get(type) ?? 0;
434	    if (claimedCount > insuredCount) {
435	      throw new Error(
436	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
437	      );
438	    }
439	  }
440	};
441	
442	// A damage is what an incident cost the owner, so it cannot be negative. Zero
443	// is left alone: the spec forbids only negative amounts, and a zero damage
444	// simply pays nothing once the deductible bites.
445	const isNegative = (damage: Damage): boolean => damage.amount < 0;
446	
447	const rejectNegativeDamages = (incident: Incident): void => {
448	  const negative = incident.damages.find(isNegative);
449	  if (negative) {
450	    throw new Error(
451	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
452	    );
453	  }
454	};
455	
456	// Both guards run before any payout is computed: the spec rejects the whole
457	// claim, not just the offending entries, so a valid entry alongside an invalid
458	// one must not be paid.
459	//
460	// They are two statements rather than a list of validations. Their signatures
461	// differ (only the first needs the policy), so a uniform list could hold them
462	// only by giving the second a parameter it ignores. And the order is not
463	// incidental: rejectUnmatchedDamages must come first because it is what makes
464	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
465	// a sequenced line here but would vanish into array order in a list.
466	//
467	// Two is the whole set, not a stage on the way to more. The spec's remaining
468	// claim-side error — a damage naming an item type the office does not insure —
469	// needs no guard of its own: rejectUnmatchedDamages already catches it, because
470	// a type the office does not insure cannot be in the policy either and so is
471	// covered zero times. See its comment for why that is the more precise
472	// diagnosis rather than a lucky accident.
473	const payoutForIncident = (policy: Policy, incident: Incident): number => {
474	  rejectUnmatchedDamages(policy, incident);
475	  rejectNegativeDamages(incident);
476	  return sum(
477	    incident.damages.map((damage) =>
478	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
479	    ),
480	  );
481	};
482	
483	// The damage decides what a claim is WORTH; the cap decides what there is left
484	// to pay it WITH. Once the cap is spent the office pays what remains, not what
485	// was asked — so the cap bounds the payout before it is charged against it.
486	//
487	// This is the guarantee that makes drawDownCap's subtraction safe: a payout that
488	// has passed through here can never exceed the balance, so the balance can never
489	// go negative. The two are a pair — bound, then spend — and neither is sound
490	// without the other.
491	const payoutWithinCap = (payout: number, remainingCap: number): number =>
492	  Math.min(payout, remainingCap);
493	
494	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
495	// it and the rest carries forward to the next claim against the same policy.
496	// The balance stays non-negative because payoutWithinCap has already bounded
497	// what is spent — this subtraction does not defend itself, it relies on that.
498	//
499	// Naming the draw-down separates what the cap DOES from how a claim is assembled
500	// — the one line in runClaim that was arithmetic rather than plumbing.
501	const drawDownCap = (remainingCap: number, payout: number): number =>
502	  remainingCap - payout;
503	
504	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
505	  // A claim naming a policy that does not exist is a spec error case, but no
506	  // test drives it yet. The assertion stands in until one does — at which point
507	  // the missing case becomes the error branch rather than a crash.
508	  const policy = state.policies.get(step.policy)!;
509	  // Rounded before the clamp so the cap is only ever compared with, and reduced
510	  // by, whole G — a fractional payout would otherwise leave a fractional cap
511	  // behind for the next claim.
512	  const claimWorth = roundPayoutInMHPCOsFavour(
513	    payoutForIncident(policy, step.incident),
514	  );
515	  const payout = payoutWithinCap(claimWorth, policy.remainingCap);
516	  const remainingCap = drawDownCap(policy.remainingCap, payout);
517	  return {
518	    result: { payout, remainingCap },
519	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
520	  };
521	};
522	
523	// Dispatch decides once what a step is; each operation then owns both its
524	// result and how it advances the state, so no caller has to re-test step.op to
525	// know what the step did.
526	const runStep = (
527	  step: Step,
528	  customer: Customer,
529	  state: ScenarioState,
530	  stepIndex: number,
531	): StepOutcome =>
532	  step.op === "quote"
533	    ? runQuote(step, customer, state, stepIndex)
534	    : runClaim(step, state);
535	
536	// The fold carries both halves of the outcome: the results accumulated so far
537	// and the state the next step will see. Threading the state explicitly (rather
538	// than recovering it from the last result) keeps the dependency between steps
539	// visible in the type.
540	interface ScenarioRun {
541	  results: StepResult[];
542	  state: ScenarioState;
543	}
544	
545	const initialRun = (): ScenarioRun => ({ results: [], state: initialState() });
546	
547	const appendStep =
548	  (customer: Customer) =>
549	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
550	    const outcome = runStep(step, customer, run.state, stepIndex);
551	    return {
552	      results: [...run.results, outcome.result],
553	      state: outcome.state,
554	    };
555	  };
556	
557	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
558	  results: steps.reduce(appendStep(customer), initialRun()).results,
559	});
560

